  children,
  active = true,
  motionRef,
}: {
  label: string;
  onClose: () => void;
  children: ReactNode;
  active?: boolean;
  motionRef?: RefObject<HTMLDivElement | null>;
}) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (active) ref.current?.focus({ preventScroll: true });
  }, [active]);
  return (
    <div
      ref={(node) => {
        ref.current = node;
        if (motionRef) motionRef.current = node;
      }}
      tabIndex={-1}
      role="dialog"
      aria-modal="true"
      aria-label={label}
      className="viewer-modal"
      inert={!active}
      aria-hidden={!active || undefined}
      style={{ pointerEvents: active ? undefined : 'none' }}
      onKeyDown={(e) => {
        e.stopPropagation();
        if (e.key === 'Escape') {
          e.preventDefault();
          onClose();
        }
        if (e.key === 'Tab') {
          const items = Array.from(
              ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),textarea,input') ??
                [],
            ),
            first = items[0],
            last = items.at(-1);
          if (
            e.shiftKey &&
            (document.activeElement === first || document.activeElement === ref.current)
          ) {
            e.preventDefault();
            last?.focus();
          } else if (
            !e.shiftKey &&
            (document.activeElement === last || document.activeElement === ref.current)
          ) {
            e.preventDefault();
            first?.focus();
          }
        }
      }}
    >
      {children}
    </div>
  );
}
